'use strict';

// MODULES //

var dlamch = require( '@stdlib/lapack/base/dlamch' );
var min = require( '@stdlib/math/base/special/min' );


// VARIABLES //

var SFMIN = dlamch( 'S' );


// MAIN //

/**
* Computes one DQD transform in ping-pong form.
*
* ## Notes
*
* -   `Z` is a 1-D array of length >= `4 * N0` storing interleaved Q/E values.
* -   `PP` is 0 for ping, 1 for pong.
*
* @private
* @param {integer} I0 - the first index
* @param {integer} N0 - the last index
* @param {Float64Array} Z - the QD array
* @param {integer} strideZ - stride length for `Z`
* @param {NonNegativeInteger} offsetZ - starting index for `Z`
* @param {boolean} PP - ping-pong flag (0 or 1)
* @param {Float64Array} out - output array containing `DMIN`, `DMIN1`, `DMIN2`, `DN`, `DNM1`, and `DNM2` respectively
* @param {integer} strideOut - stride length for `out`
* @param {NonNegativeInteger} offsetOut - starting index of `out`
* @returns {Float64Array} output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var out = new Float64Array( 6 );
* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
*
* dlasq6( 0, 3, Z, 1, 0, 0, out, 1, 0 );
* // out => <Float64Array>[ 3.75, 3.75, 3.75, ~12.088, ~6.111, 3.75 ]
*/
function dlasq6( I0, N0, Z, strideZ, offsetZ, PP, out, strideOut, offsetOut ) {
	var dmin1;
	var dmin2;
	var dnm1;
	var dnm2;
	var emin;
	var dmin;
	var temp;
	var j4p2;
	var idx;
	var ix1;
	var ix2;
	var ix3;
	var ix4;
	var j4;
	var dn;
	var d;

	// Quick return...
	if ( ( N0 - I0 - 1 ) <= 0 ) {
		return out;
	}

	idx = offsetZ;

	j4 = offsetZ + ( strideZ * ( ( 4 * I0 ) + PP ) );
	emin = Z[ j4 + ( 4 * strideZ ) ];
	d = Z[ j4 ];
	dmin = d;

	j4 = offsetZ + ( strideZ * ( ( 4 * I0 ) + 3 ) );

	if ( PP === 0 ) {
		for ( idx = ( 4 * I0 ) + 3; idx <= ( 4 * N0 ) - 9; idx += 4 ) {
			ix1 = j4 + strideZ;
			ix2 = j4 - strideZ;
			ix3 = j4 - ( 2 * strideZ );

			Z[ ix3 ] = d + Z[ ix2 ];
			if ( Z[ ix3 ] === 0 ) {
				Z[ j4 ] = 0;
				d = Z[ ix1 ];
				dmin = d;
				emin = 0;
			} else if ( ( SFMIN * Z[ ix1 ] < Z[ ix3 ] ) &&
				( SFMIN * Z[ ix3 ] < Z[ ix1 ] ) ) {
				temp = Z[ ix1 ] / Z[ ix3 ];
				Z[ j4 ] = Z[ ix2 ] * temp;
				d *= temp;
			} else {
				Z[ j4 ] = Z[ ix1 ] * ( Z[ ix2 ] / Z[ ix3 ] );
				d = Z[ ix1 ] * ( d / Z[ ix3 ] );
			}
			dmin = min( dmin, d );
			emin = min( emin, Z[ j4 ] );
			j4 += 4 * strideZ;
		}
	} else {
		for ( idx = ( 4 * I0 ) + 3; idx <= ( 4 * N0 ) - 9; idx += 4 ) {
			ix1 = j4 + ( 2 * strideZ );
			ix2 = j4 - strideZ;
			ix3 = j4 - ( 2 * strideZ );
			ix4 = j4 - ( 3 * strideZ );

			Z[ ix4 ] = d + Z[ j4 ];
			if ( Z[ ix4 ] === 0 ) {
				Z[ ix2 ] = 0;
				d = Z[ ix1 ];
				dmin = d;
				emin = 0;
			} else if ( ( SFMIN * Z[ ix1 ] < Z[ ix4 ] ) &&
				( SFMIN * Z[ ix4 ] < Z[ ix1 ] ) ) {
				temp = Z[ ix1 ] / Z[ ix4 ];
				Z[ ix2 ] = Z[ j4 ] * temp;
				d *= temp;
			} else {
				Z[ ix2 ] = Z[ ix1 ] * ( Z[ j4 ] / Z[ ix4 ] );
				d = Z[ ix1 ] * ( d / Z[ ix4 ] );
			}
			dmin = min( dmin, d );
			emin = min( emin, Z[ ix2 ] );
			j4 += 4 * strideZ;
		}
	}

	// Unroll last two steps.
	dnm2 = d;
	dmin2 = dmin;
	j4 = offsetZ + ( strideZ * ( ( 4 * N0 ) - 5 - PP ) );
	j4p2 = j4 + ( strideZ * ( ( 2 * PP ) - 1 ) );

	ix1 = j4 - ( 2 * strideZ );
	ix2 = j4p2 + ( 2 * strideZ );

	Z[ ix1 ] = dnm2 + Z[ j4p2 ];
	if ( Z[ ix1 ] === 0 ) {
		Z[ j4 ] = 0;
		dnm1 = Z[ ix2 ];
		dmin = dnm1;
		emin = 0;
	} else if ( ( SFMIN * Z[ ix2 ] < Z[ ix1 ] ) && ( SFMIN * Z[ ix1 ] < Z[ ix2 ] ) ) {
		temp = Z[ ix2 ] / Z[ ix1 ];
		Z[ j4 ] = Z[ j4p2 ] * temp;
		dnm1 = dnm2 * temp;
	} else {
		Z[ j4 ] = Z[ ix2 ] * ( Z[ j4p2 ] / Z[ ix1 ] );
		dnm1 = Z[ ix2 ] * ( dnm2 / Z[ ix1 ] );
	}
	dmin = min( dmin, dnm1 );

	dmin1 = dmin;
	j4 += 4 * strideZ;
	j4p2 += 4 * strideZ;

	ix1 = j4 - ( 2 * strideZ );
	ix2 = j4p2 + ( 2 * strideZ );

	Z[ ix1 ] = dnm1 + Z[ j4p2 ];
	if ( Z[ ix1 ] === 0 ) {
		Z[ j4 ] = 0;
		dn = Z[ ix2 ];
		dmin = dn;
		emin = 0;
	} else if ( ( SFMIN * Z[ ix2 ] < Z[ ix1 ] ) &&
		( SFMIN * Z[ ix1 ] < Z[ ix2 ] ) ) {
		temp = Z[ ix2 ] / Z[ ix1 ];
		Z[ j4 ] = Z[ j4p2 ] * temp;
		dn = dnm1 * temp;
	} else {
		Z[ j4 ] = Z[ ix2 ] * ( Z[ j4p2 ] / Z[ ix1 ] );
		dn = Z[ ix2 ] * ( dnm1 / Z[ ix1 ] );
	}
	dmin = min( dmin, dn );

	Z[ j4 + ( 2 * strideZ ) ] = dn;
	Z[ offsetZ + ( strideZ * ( ( 4 * ( N0 ) ) + 3 - PP ) ) ] = emin;

	idx = offsetOut;
	out[ idx ] = dmin;
	idx += strideOut;
	out[ idx ] = dmin1;
	idx += strideOut;
	out[ idx ] = dmin2;
	idx += strideOut;
	out[ idx ] = dn;
	idx += strideOut;
	out[ idx ] = dnm1;
	idx += strideOut;
	out[ idx ] = dnm2;

	return out;
}


// EXPORTS //

module.exports = dlasq6;
